// source: attention-state.go

/**
 * State is where an item sits in its lifecycle. The three values are the
 * schema's own; `open` is the only state an arm renders to the operator.
 */
export type State = string;
/**
 * OpenState is pushed and not yet answered.
 */
export const OpenState: State = "open";
/**
 * AwaitingEvidenceState is answered with a `done`-class claim whose effect
 * has not been observed yet.
 * ⚠️ It exists because a `done` answer is a CLAIM, not a fact. Measured
 * 2026-11-13: a card was answered `done — reviewed and flipped both`, and
 * minutes later the two PRs it named were still `OPEN isDraft=true
 * reviewDecision=REVIEW_REQUIRED` with unchanged heads. The card read as
 * satisfied while the work was untouched, and nothing noticed — a false
 * `done` is invisible, which is strictly worse than an ask nobody answered.
 * An item in this state is off the open queue but NOT satisfied: the answer
 * is recorded, EvidenceClaim names what would prove it, and the sweep closes
 * it only when that claim is observed or reopens it when the deadline passes.
 */
export const AwaitingEvidenceState: State = "awaiting_evidence";
/**
 * AnsweredState is answered and routed back to producer_id.
 */
export const AnsweredState: State = "answered";
/**
 * ClosedState has left the queue. Terminal.
 */
export const ClosedState: State = "closed";
/**
 * States is a collection of State.
 */
export type States = State[];

//////////
// source: close-reason.go

/**
 * CloseReason is why an item left the queue without an answer.
 * It exists because ClosedAt records that an item left but not which closer
 * moved it, and for a card that was never answered that is the whole question:
 * several mechanisms close items, and before this field the store could not say
 * which one had. It is a name for a PATH, never a constant — a value such as
 * "closed" or "swept" would satisfy a non-empty check while telling a reader
 * nothing, which is the shape the field exists to remove.
 * It is optional. An empty CloseReason stores an item whose close was caused by
 * an answer, which AnsweredAt and AnsweredBy already record, and which every
 * item closed before this field existed reads as.
 */
export type CloseReason = string;
/**
 * RedundantReraiseCloseReason is a re-raise whose ask had already been
 * answered, closed by closeRedundantReraises.
 */
export const RedundantReraiseCloseReason: CloseReason = "redundant_reraise";
/**
 * UnanswerableCloseReason is a row whose ask could not be captured.
 */
export const UnanswerableCloseReason: CloseReason = "unanswerable";
/**
 * CloseReasons is a collection of CloseReason.
 */
export type CloseReasons = CloseReason[];

//////////
// source: decision.go

/**
 * Decision is what an answer decided. It exists because an arm is not a
 * decision: AnsweredBy names the arm that supplied the answer, and the same arm
 * supplies an allow and a deny, so before this field an item answered allow and
 * one answered deny were the same record and "was this answered" could not be
 * told from "what was decided".
 * It is optional, and the schema adds no write-time rejection for an omitted
 * value. An empty Decision therefore stores an item with no verdict recorded —
 * which is what every item answered before this field existed reads as, and what
 * a message- or ack-class item reads as, since neither carries a
 * machine-readable verdict.
 */
export type Decision = string;
/**
 * AllowDecision is the decision to let the parked call proceed.
 */
export const AllowDecision: Decision = "allow";
/**
 * DenyDecision is the decision to refuse it.
 */
export const DenyDecision: Decision = "deny";
/**
 * Decisions is a collection of Decision.
 */
export type Decisions = Decision[];

