// source: producer-kind.go

/**
 * ProducerKind is what kind of thing the producer is. It exists so a
 * per-producer interrupt rate can be measured later without a schema change.
 */
export type ProducerKind = string;
/**
 * SessionProducerKind is a Claude Code session.
 */
export const SessionProducerKind: ProducerKind = "session";
/**
 * ManagerProducerKind is a manager session — the layer that resolves
 * prompts between a worker and the operator. It is deliberately distinct
 * from SessionProducerKind, because "a manager asked" and "a worker
 * asked" are different populations, and the per-producer rate this field
 * exists to measure is only useful if they can be told apart.
 * ⚠️ It is a *kind*, never a route. The jump back to a manager's pane
 * resolves from LivenessRef — pkg/provenance.go never reads ProducerKind
 * — so adding this value grants no jump and widens no liveness model.
 * A `pane:` liveness model stays rejected: a pane id is a lease, so a
 * liveness verdict keyed on one resolves to another session's pane
 * rather than failing.
 */
export const ManagerProducerKind: ProducerKind = "manager";
/**
 * AgentProducerKind is a k8s Pattern B agent.
 */
export const AgentProducerKind: ProducerKind = "agent";
/**
 * CronProducerKind is a cron job.
 */
export const CronProducerKind: ProducerKind = "cron";
/**
 * DarkFactoryProducerKind is a dark-factory run.
 */
export const DarkFactoryProducerKind: ProducerKind = "dark-factory";
/**
 * ProducerKinds is a collection of ProducerKind.
 */
export type ProducerKinds = ProducerKind[];

//////////
// source: provenance-class.go

/**
 * ProvenanceClass is where the claim came from — declared by the producer,
 * stored, never derived. It answers "how was this claim obtained", which is
 * distinct from ProducerKind's "what kind of thing asked".
 * An empty ProvenanceClass is accepted: it marks a pre-2026-09-23 item pushed
 * before this field existed. See the attention item schema § Fields,
 * `provenance_class`, and silence 9.
 */
export type ProvenanceClass = string;
/**
 * HookProvenanceClass is a harness hook event: PermissionRequest,
 * AskUserQuestion.
 */
export const HookProvenanceClass: ProvenanceClass = "hook";
/**
 * ExplicitProvenanceClass is an explicit producer call carrying a stable
 * id.
 */
export const ExplicitProvenanceClass: ProvenanceClass = "explicit";
/**
 * ThirdPartyProvenanceClass is built from a third party's rendered text —
 * a peer's pane, a board, someone else's log line. Disallowed by the
 * stack's own rule; it exists only so its absence can be counted.
 */
export const ThirdPartyProvenanceClass: ProvenanceClass = "third_party";
/**
 * ProvenanceClasses is a collection of ProvenanceClass.
 */
export type ProvenanceClasses = ProvenanceClass[];

//////////
// source: question.go

/**
 * Question is one question unit of an item that carries more than one. Each is
 * rendered as a tab across the top of the board's card, with its own payload,
 * its own control and its own options.
 * It exists because an item otherwise holds exactly one question, so a card
 * asking several things at once had no unit for a tab to be and no place to put
 * a second question's options. It carries Payload's contract — plain
 * operator-facing sentences, no machine handles — because it is the question
 * the operator reads.
 */
export interface Question {
  /**
   * Tab is the label the board renders on this question's tab, and the value
   * a QuestionAnswer names in its Question field.
   */
  tab: string;
  /**
   * Payload is the question itself.
   */
  payload: Payload;
  /**
   * Cardinality is whether this question takes one pick or many. Absent means
   * single, exactly as the item-level field does.
   */
  cardinality?: AnswerCardinality;
  /**
   * Options are this question's choices.
   */
  options?: AnswerOptions;
}
/**
 * Questions is an ordered list of Question — the question units of a
 * multi-question item, one per rendered tab.
 */
export type Questions = Question[];

